-- submissions/source
-- The source a submission points at: a news link, or a witness statement (private, shown to reviewers only).
--
-- Parameters, with the example values used to render this file:
--   $1 = "0199c8a0-0000-7000-8000-00000000000a"
--
-- Generated by `pnpm db:queries` from lib/db/queries/submissions.ts. Do not edit by hand.

select id, kind, url, text_private as "textPrivate"
from sources
where id = $1;
